// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 ethAmount) public {
        ethAmount = bound(ethAmount, 0, address(c).balance + 1e18 ether);
        vm.deal(address(c), ethAmount);
        vm.prank(c.owner());
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok || address(c).balance == 0);
    }
}
